import {
  ArrowLeft, Phone, MessageSquare, MapPin, Home, Plus, Send,
  Calendar, Clock, User, Target, AlertTriangle, ShieldAlert,
  RotateCcw, GripHorizontal, BarChart3, TrendingUp,
} from "lucide-react";

const STAGES = ["new", "contacted", "requirement_confirmed", "solution_submitted", "quotation_submitted", "negotiation", "pending_decision", "won", "lost"];
const STAGE_LABELS: Record<string, string> = {
  new: "New Lead", contacted: "Contacted", requirement_confirmed: "Req Confirmed",
  solution_submitted: "Solution Sub.", quotation_submitted: "Quotation Sub.",
  negotiation: "Negotiation", pending_decision: "Pending Decision",
  won: "Won", lost: "Lost",
};
const STAGE_COLORS: Record<string, string> = {
  new: "bg-gray-500/10 text-gray-400", contacted: "bg-amber-500/10 text-amber-400",
  requirement_confirmed: "bg-yellow-500/10 text-yellow-400", solution_submitted: "bg-rose-500/10 text-rose-400",
  quotation_submitted: "bg-purple-500/10 text-purple-400", negotiation: "bg-blue-500/10 text-blue-400",
  pending_decision: "bg-amber-500/10 text-amber-400", won: "bg-emerald-500/10 text-emerald-400",
  lost: "bg-gray-500/10 text-gray-400",
};
const STATUS_LABELS: Record<string, { label: string; color: string; bg: string }> = {
  hot: { label: "🔥 Hot", color: "text-rose-400", bg: "bg-rose-500/10" },
  warm: { label: "☀️ Warm", color: "text-amber-400", bg: "bg-amber-500/10" },
  cold: { label: "❄️ Cold", color: "text-sky-400", bg: "bg-sky-500/10" },
  dormant: { label: "💤 Dormant", color: "text-gray-400", bg: "bg-gray-500/10" },
};
const PROBABILITIES = [10, 30, 50, 70, 90];
const LOST_REASONS = ["Price", "Competitor", "No Budget", "Project Cancelled", "Project Delayed", "No Response", "Other"];

interface Lead {
  id: string; source: string; quality: string; stage: string;
  customer_name: string | null; phone: string | null; email: string | null;
  property_type: string | null; property_size_sqm: number | null;
  location: string | null; budget_range: string | null;
  service_needs: string[] | null; ai_summary: string | null;
  ai_tags: string[] | null; ai_quality: string | null;
  created_at: string; updated_at: string;
  disqualified_candidate: boolean; notes: string | null;

  // New CRM fields
  lead_status: string | null; win_probability: number | null;
  stage_changed_at: string | null;
  decision_maker: string | null; decision_date: string | null; competitor: string | null;
  last_contact_date: string | null; next_followup_date: string | null;
  next_action: string | null; followup_count: number | null;
  lost_reason: string | null; lost_at: string | null;
  sales_manager_review: boolean; recovery_candidate: boolean;
  transfer_candidate: boolean; hold_since: string | null;

  // Attribution
  source_platform: string | null; source_channel: string | null;
  campaign_id: string | null; campaign_name: string | null;
  adset_id: string | null; adset_name: string | null;
  ad_id: string | null; ad_name: string | null;
  creative_id: string | null; creative_name: string | null;
  form_id: string | null; form_name: string | null;
  utm_source: string | null; utm_medium: string | null;
  utm_campaign: string | null; utm_content: string | null; utm_term: string | null;
  landing_page: string | null; referrer: string | null;
  first_touch_at: string | null; last_touch_at: string | null;

  assigned_to: string | null; rep_name: string | null;
  quotation_value: number | null;
}

interface Activity {
  id: string; type: string; content: string; ai_generated: boolean; created_at: string;
}
interface BusinessEvent {
  id: string; event_type: string; description: string; event_data: any; created_at: string;
}

function fmtAED(v: number | null | undefined): string {
  if (v == null || v === 0) return "—";
  if (v >= 1_000_000) return `AED ${(v / 1_000_000).toFixed(1)}M`;
  if (v >= 1_000) return `AED ${(v / 1_000).toFixed(0)}K`;
  return `AED ${v.toLocaleString()}`;
}
function daysSince(d: string | null): number | null {
  if (!d) return null;
  return Math.floor((Date.now() - new Date(d).getTime()) / 86_400_000);
}

export default function LeadDetailPage() {
  const { id } = useParams<{ id: string }>();
  const router = useRouter();
  const supabase = createClient();
  const { t, lang } = useLanguage();
  const [lead, setLead] = useState<Lead | null>(null);
  const [activities, setActivities] = useState<Activity[]>([]);
  const [events, setEvents] = useState<BusinessEvent[]>([]);
  const [noteText, setNoteText] = useState("");
  const [updating, setUpdating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const [editField, setEditField] = useState<string | null>(null);
  const [editValue, setEditValue] = useState<string>("");

  const fetchData = useCallback(async () => {
    setLoading(true);
    setError(null);
    const { data: l, error: err1 } = await supabase.from("leads").select("*").eq("id", id).single();
    if (err1) {
      console.error("Failed to fetch lead:", err1);
      setError("加载失败，请刷新重试");
      setLoading(false);
      return;
    }
    if (l) setLead(l);
    const { data: a, error: err2 } = await supabase.from("activities").select("*").eq("lead_id", id).order("created_at", { ascending: false });
    if (err2) console.error("Failed to fetch activities:", err2);
    if (a) setActivities(a);
    const { data: e, error: err3 } = await supabase.from("business_events").select("*").eq("lead_id", id).order("created_at", { ascending: false }).limit(50);
    if (err3) console.error("Failed to fetch business events:", err3);
    if (e) setEvents(e);
    setLoading(false);
  }, [id]);

  useEffect(() => { fetchData(); }, [fetchData]);

  async function writeEvent(eventType: string, description: string, eventData?: Record<string, any>) {
    await supabase.from("business_events").insert({
      lead_id: id, event_type: eventType, description, event_data: eventData || {},
    });
  }

  async function updateField(field: string, value: any, eventType?: string, eventDesc?: string) {
    setUpdating(true);
    const updates: Record<string, any> = { updated_at: new Date().toISOString() };
    updates[field] = value;
    await supabase.from("leads").update(updates).eq("id", id);
    if (eventType && eventDesc) {
      await supabase.from("activities").insert({ lead_id: id, type: eventType, content: eventDesc });
      await writeEvent(eventType, eventDesc, { [field]: value });
    }
    setEditField(null);
    fetchData();
    setUpdating(false);
  }

  async function updateStage(stage: string) {
    await updateField("stage", stage, "stage_change", `${t("leadDetail.eventTypes.stage_changed")} → ${t(`stageLabels.${stage}`)}`);
  }

  async function addNote() {
    if (!noteText.trim()) return;
    await supabase.from("activities").insert({ lead_id: id, type: "note", content: noteText.trim() });
    await writeEvent("note_added", `${t("leadDetail.eventTypes.note_added")}: ${noteText.trim()}`);
    await supabase.from("leads").update({ last_contact_date: new Date().toISOString(), updated_at: new Date().toISOString() }).eq("id", id);
    setNoteText("");
    fetchData();
  }

  async function createQuote() {
    const { data } = await supabase.from("quotes").insert({ lead_id: id, status: "draft", version: 1 }).select("id").single();
    if (data) {
      await supabase.from("activities").insert({ lead_id: id, type: "quote_sent", content: `${t("leadDetail.eventTypes.quotation_sent")} #${data.id.slice(0, 8)}` });
      await writeEvent("quotation_sent", `${t("leadDetail.eventTypes.quotation_sent")} #${data.id.slice(0, 8)}`);
      await supabase.from("leads").update({ stage: "quotation_submitted", updated_at: new Date().toISOString() }).eq("id", id);
      fetchData();
    }
  }

  if (loading) return <div className="text-gray-500 p-8">{t("common.loading")}</div>;
  if (error) return <ErrorState message={error} onRetry={fetchData} />;
  if (!lead) return <div className="text-gray-500 p-8">{t("common.loading")}</div>;

  const dSinceContact = daysSince(lead.last_contact_date || lead.updated_at);
  const isYellow = dSinceContact !== null && dSinceContact >= 7 && dSinceContact < 14 && !["won", "lost"].includes(lead.stage);
  const isRed = dSinceContact !== null && dSinceContact >= 14 && !["won", "lost"].includes(lead.stage);

  return (
    <div className="max-w-5xl space-y-6">
      {/* Back + header */}
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={() => router.push("/leads")} className="text-gray-400">
          <ArrowLeft className="w-5 h-5" />
        </Button>
        <div className="flex-1">
          <div className="flex items-center gap-2">
            <h1 className="text-2xl font-bold text-white">
              {lead.customer_name || lead.phone || (lang === "zh" ? "未命名" : "Unnamed")}
            </h1>
            {lead.lead_status && (
              <span className={cn("text-xs px-2 py-0.5 rounded font-medium",
                lead.lead_status === "hot" ? "bg-rose-500/10 text-rose-400" :
                lead.lead_status === "warm" ? "bg-amber-500/10 text-amber-400" :
                lead.lead_status === "cold" ? "bg-sky-500/10 text-sky-400" :
                "bg-gray-500/10 text-gray-400")}>
                {lead.lead_status === "hot" ? "🔥 " : lead.lead_status === "warm" ? "☀️ " : lead.lead_status === "cold" ? "❄️ " : "💤 "}
                {t(`statusLabels.${lead.lead_status}`)}
              </span>
            )}
          </div>
          <p className="text-gray-500 text-sm">
            {new Date(lead.created_at).toLocaleDateString(lang === "zh" ? "zh-CN" : "en-GB")} · {lead.source}
            {lead.rep_name && ` · ${lead.rep_name}`}
          </p>
        </div>
        <Badge className={STAGE_COLORS[lead.stage] || ""}>
          {t(`stageLabels.${lead.stage}`) || lead.stage}
        </Badge>
        {lead.win_probability != null && (
          <Badge className={cn(lead.win_probability >= 70 ? "bg-emerald-500/10 text-emerald-400" : lead.win_probability >= 30 ? "bg-amber-500/10 text-amber-400" : "bg-gray-500/10 text-gray-400")}>
            {lead.win_probability}%
          </Badge>
        )}
        {/* Manager flags */}
        {lead.recovery_candidate && <Badge className="bg-orange-500/10 text-orange-400">Recovery</Badge>}
        {lead.transfer_candidate && <Badge className="bg-red-500/10 text-red-400">Transfer</Badge>}
        {lead.sales_manager_review && <Badge className="bg-purple-500/10 text-purple-400">{lang === "zh" ? "主管审阅" : "Manager Review"}</Badge>}
      </div>

      {/* Alert banner */}
      {(isYellow || isRed || lead.recovery_candidate || lead.transfer_candidate) && (
        <div className={cn("px-4 py-2 rounded-lg text-sm flex items-center gap-2",
          isRed ? "bg-red-500/10 text-red-400 border border-red-500/20" :
          isYellow ? "bg-amber-500/10 text-amber-400 border border-amber-500/20" :
          lead.transfer_candidate ? "bg-red-500/10 text-red-400 border border-red-500/20" :
          "bg-orange-500/10 text-orange-400 border border-orange-500/20")}>
          <AlertTriangle className="w-4 h-4 shrink-0" />
          {isRed ? (lang === "zh" ? `🔴 红色预警 — ${dSinceContact}天未跟进` : `🔴 Red Alert — ${dSinceContact}d no follow-up`) :
           isYellow ? (lang === "zh" ? `🟡 黄色预警 — ${dSinceContact}天未跟进` : `🟡 Yellow Alert — ${dSinceContact}d no follow-up`) :
           lead.recovery_candidate ? (lang === "zh" ? "🔄 Recovery Pool — 报价后超14天无动作" : "🔄 Recovery Pool — No action 14d after quote") :
           lead.transfer_candidate ? (lang === "zh" ? "↗️ Transfer Pool — 报价后超30天无动作" : "↗️ Transfer Pool — No action 30d after quote") : ""}
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* ────── Left: Main Info ────── */}
        <div className="lg:col-span-2 space-y-6">
          {/* AI Summary */}
          {lead.ai_summary && (
            <Card className="bg-gray-900 border-gray-800">
              <CardHeader className="pb-2">
                <CardTitle className="text-sm text-gray-400 flex items-center gap-2">{t("leadDetail.aiAnalysis")}</CardTitle>
              </CardHeader>
              <CardContent>
                <p className="text-white">{lead.ai_summary}</p>
                {lead.ai_tags && lead.ai_tags.length > 0 && (
                  <div className="flex gap-2 mt-3 flex-wrap">
                    {lead.ai_tags.map((t) => (
                      <Badge key={t} variant="outline" className="text-xs border-gray-700 text-gray-400">{t}</Badge>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          )}

          {/* Decision Info Card */}
          <Card className="bg-gray-900 border-gray-800">
            <CardHeader className="pb-2">
              <CardTitle className="text-sm text-gray-400 flex items-center gap-2">
                <Target className="w-4 h-4" /> {t("leadDetail.decisionInfo")}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div>
                  <Label className="text-gray-500 text-xs">{t("leadDetail.decisionMaker")}</Label>
                  {editField === "decision_maker" ? (
                    <div className="flex gap-1 mt-1">
                      <input autoFocus value={editValue} onChange={(e) => setEditValue(e.target.value)}
                        onKeyDown={(e) => { if (e.key === "Enter") updateField("decision_maker", editValue, "note_added", `${t("leadDetail.decisionMaker")}: ${editValue}`); if (e.key === "Escape") setEditField(null); }}
                        className="flex-1 h-8 text-xs bg-gray-800 border border-gray-700 rounded px-2 text-white" />
                    </div>
                  ) : (
                    <p className="text-white mt-1 cursor-pointer hover:text-copper-400" onClick={() => { setEditField("decision_maker"); setEditValue(lead.decision_maker || ""); }}>
                      {lead.decision_maker || <span className="text-gray-600">{t("leadDetail.placeholderClickToFill")}</span>}
                    </p>
                  )}
                </div>
                <div>
                  <Label className="text-gray-500 text-xs">{t("leadDetail.competitor")}</Label>
                  {editField === "competitor" ? (
                    <div className="flex gap-1 mt-1">
                      <input autoFocus value={editValue} onChange={(e) => setEditValue(e.target.value)}
                        onKeyDown={(e) => { if (e.key === "Enter") updateField("competitor", editValue, "note_added", `${t("leadDetail.competitor")}: ${editValue}`); if (e.key === "Escape") setEditField(null); }}
                        className="flex-1 h-8 text-xs bg-gray-800 border border-gray-700 rounded px-2 text-white" />
                    </div>
                  ) : (
                    <p className="text-white mt-1 cursor-pointer hover:text-copper-400" onClick={() => { setEditField("competitor"); setEditValue(lead.competitor || ""); }}>
                      {lead.competitor || <span className="text-gray-600">{t("leadDetail.placeholderClickToFill")}</span>}
                    </p>
                  )}
                </div>
                <div>
                  <Label className="text-gray-500 text-xs">{t("leadDetail.decisionDate")}</Label>
                  {editField === "decision_date" ? (
                    <input type="date" autoFocus value={editValue} onChange={(e) => setEditValue(e.target.value)}
                      onBlur={() => updateField("decision_date", editValue || null, "note_added", `${t("leadDetail.decisionDate")}: ${editValue || (lang === "zh" ? "清除" : "Cleared")}`)}
                      className="w-full h-8 text-xs bg-gray-800 border border-gray-700 rounded px-2 text-white mt-1" />
                  ) : (
                    <p className="text-white mt-1 cursor-pointer hover:text-copper-400" onClick={() => { setEditField("decision_date"); setEditValue(lead.decision_date || ""); }}>
                      {lead.decision_date ? new Date(lead.decision_date).toLocaleDateString(lang === "zh" ? "zh-CN" : "en-GB") : <span className="text-gray-600">{t("leadDetail.placeholderClickToFill")}</span>}
                    </p>
                  )}
                </div>
                <div>
                  <Label className="text-gray-500 text-xs">{t("leadDetail.probability")}</Label>
                  <div className="flex gap-1 mt-1 flex-wrap">
                    {PROBABILITIES.map(p => (
                      <button key={p}
                        className={cn("text-[10px] px-2 py-1 rounded border transition-colors",
                          lead.win_probability === p ? "bg-copper-500 text-black border-copper-500" : "border-gray-700 text-gray-400 hover:border-gray-500")}
                        onClick={() => updateField("win_probability", p, "probability_changed", `${t("leadDetail.probability")}: ${p}%`)}>
                        {p}%
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Follow-up Management Card */}
          <Card className="bg-gray-900 border-gray-800">
            <CardHeader className="pb-2">
              <CardTitle className="text-sm text-gray-400 flex items-center gap-2">
                <Calendar className="w-4 h-4" /> {t("leadDetail.followupManagement")}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div>
                  <Label className="text-gray-500 text-xs">{t("leadDetail.lastContact")}</Label>
                  <p className="text-white mt-1">
                    {lead.last_contact_date ? new Date(lead.last_contact_date).toLocaleDateString(lang === "zh" ? "zh-CN" : "en-GB") : "—"}
                    {dSinceContact !== null && <span className={cn("ml-2", isRed ? "text-red-400" : isYellow ? "text-amber-400" : "text-gray-500")}>{lang === "zh" ? `(${dSinceContact}天前)` : `(${dSinceContact}d ago)`}</span>}
                  </p>
                </div>
                <div>
                  <Label className="text-gray-500 text-xs">{t("leadDetail.followUpCount")}</Label>
                  <p className="text-white mt-1">{lang === "zh" ? `${lead.followup_count || 0} 次` : `${lead.followup_count || 0} times`}</p>
                </div>
                <div>
                  <Label className="text-gray-500 text-xs">{t("leadDetail.nextFollowUp")} *{lang === "zh" ? "必填" : "Required"}</Label>
                  {editField === "next_followup_date" ? (
                    <input type="date" autoFocus value={editValue} onChange={(e) => setEditValue(e.target.value)}
                      onBlur={() => { if (editValue) updateField("next_followup_date", editValue, "followup_scheduled", `${t("leadDetail.nextFollowUp")}: ${editValue}`); }}
                      className="w-full h-8 text-xs bg-gray-800 border border-gray-700 rounded px-2 text-white mt-1" />
                  ) : (
                    <p className={cn("mt-1 cursor-pointer hover:text-copper-400",
                      !lead.next_followup_date ? "text-rose-400 font-medium" : "text-white")}
                      onClick={() => { setEditField("next_followup_date"); setEditValue(lead.next_followup_date || ""); }}>
                      {lead.next_followup_date ? new Date(lead.next_followup_date).toLocaleDateString(lang === "zh" ? "zh-CN" : "en-GB") : (lang === "zh" ? "⚠️ 必填，点击设置" : "⚠️ Required, click to set")}
                    </p>
                  )}
                </div>
                <div>
                  <Label className="text-gray-500 text-xs">{t("leadDetail.nextAction")} *{lang === "zh" ? "必填" : "Required"}</Label>
                  {editField === "next_action" ? (
                    <div className="flex gap-1 mt-1">
                      <input autoFocus value={editValue} onChange={(e) => setEditValue(e.target.value)}
                        onKeyDown={(e) => { if (e.key === "Enter" && editValue.trim()) updateField("next_action", editValue.trim(), "followup_scheduled", `${t("leadDetail.nextAction")}: ${editValue.trim()}`); if (e.key === "Escape") setEditField(null); }}
                        className="flex-1 h-8 text-xs bg-gray-800 border border-gray-700 rounded px-2 text-white" />
                    </div>
                  ) : (
                    <p className={cn("mt-1 cursor-pointer hover:text-copper-400",
                      !lead.next_action ? "text-rose-400 font-medium" : "text-white")}
                      onClick={() => { setEditField("next_action"); setEditValue(lead.next_action || ""); }}>
                      {lead.next_action || (lang === "zh" ? "⚠️ 必填，点击设置" : "⚠️ Required, click to set")}
                    </p>
                  )}
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Lost Reason (if lost) */}
          {lead.stage === "lost" && (
            <Card className="bg-gray-900 border-red-800/30">
              <CardHeader className="pb-2">
                <CardTitle className="text-sm text-red-400 flex items-center gap-2">
                  <AlertTriangle className="w-4 h-4" /> {t("leadDetail.lostInfo")}
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-sm">
                  <Label className="text-gray-500 text-xs">{t("leadDetail.lostReason")}</Label>
                  <div className="flex gap-1 mt-1 flex-wrap">
                    {LOST_REASONS.map(r => (
                      <button key={r}
                        className={cn("text-[10px] px-2 py-1 rounded border transition-colors",
                          lead.lost_reason === r ? "bg-rose-500 text-white border-rose-500" : "border-gray-700 text-gray-400 hover:border-gray-500")}
                        onClick={() => updateField("lost_reason", r, "lost_reason_set", `${t("leadDetail.lostReason")}: ${t(`lostReasons.${r}`)}`)}>
                        {t(`lostReasons.${r}`)}
                      </button>
                    ))}
                  </div>
                  {lead.lost_at && (
                    <p className="text-gray-400 text-xs mt-2">{lang === "zh" ? "输单时间: " : "Lost at: "}{new Date(lead.lost_at).toLocaleString(lang === "zh" ? "zh-CN" : "en-GB")}</p>
                  )}
                </div>
              </CardContent>
            </Card>
          )}

          {/* Attribution Card */}
          <Card className="bg-gray-900 border-gray-800">
            <CardHeader className="pb-2">
              <CardTitle className="text-sm text-gray-400 flex items-center gap-2">
                <BarChart3 className="w-4 h-4" /> {t("leadDetail.attribution")}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 text-xs">
                {[
                  { label: t("leadDetail.sourcePlatform"), value: lead.source_platform },
                  { label: t("leadDetail.sourceChannel"), value: lead.source_channel },
                  { label: "Campaign ID", value: lead.campaign_id },
                  { label: "Campaign", value: lead.campaign_name },
                  { label: "Adset ID", value: lead.adset_id },
                  { label: "Adset", value: lead.adset_name },
                  { label: "Ad ID", value: lead.ad_id },
                  { label: "Ad Name", value: lead.ad_name },
                  { label: "Creative ID", value: lead.creative_id },
                  { label: "Creative", value: lead.creative_name },
                  { label: "Form ID", value: lead.form_id },
                  { label: "Form Name", value: lead.form_name },
                  { label: "UTM Source", value: lead.utm_source },
                  { label: "UTM Medium", value: lead.utm_medium },
                  { label: "UTM Campaign", value: lead.utm_campaign },
                  { label: "UTM Content", value: lead.utm_content },
                  { label: "UTM Term", value: lead.utm_term },
                  { label: "Landing Page", value: lead.landing_page },
                  { label: "Referrer", value: lead.referrer },
                ].map(({ label, value }) => (
                  <div key={label}>
                    <p className="text-gray-500">{label}</p>
                    <p className="text-white truncate" title={value || ""}>{value || "—"}</p>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>

          {/* Activities + Events Timeline */}
          <Card className="bg-gray-900 border-gray-800">
            <CardHeader className="pb-2">
              <CardTitle className="text-sm text-gray-400 flex items-center gap-2">
                <Clock className="w-4 h-4" /> {t("leadDetail.timeline")}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              {/* Add note */}
              <div className="flex gap-2">
                <Textarea
                  placeholder={t("leadDetail.placeholderNote")}
                  value={noteText}
                  onChange={(e) => setNoteText(e.target.value)}
                  className="bg-gray-950 border-gray-700 text-white resize-none h-20"
                  onKeyDown={(e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); addNote(); } }}
                />
                <Button size="icon" onClick={addNote} disabled={!noteText.trim()} className="bg-gold-500 hover:bg-gold-600 text-black h-10 w-10 shrink-0 self-end">
                  <Send className="w-4 h-4" />
                </Button>
              </div>

              <Separator className="bg-gray-800" />

              {/* Timeline - merge activities + events */}
              <div className="space-y-3">
                {[...activities.map(a => ({ ...a, _type: "activity" as const })),
                   ...events.map(e => ({ id: e.id, type: e.event_type, content: e.description, ai_generated: false, created_at: e.created_at, _type: "event" as const }))]
                  .sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime())
                  .slice(0, 100).map((item) => (
                    <div key={`${item._type}-${item.id}`} className="flex gap-3 text-sm">
                      <div className={cn("w-1.5 h-1.5 rounded-full mt-1.5 shrink-0",
                        item.type.includes("stage") ? "bg-amber-500" :
                        item.type.includes("note") ? "bg-gray-500" :
                        item.type.includes("quote") ? "bg-blue-500" :
                        item.type.includes("lost") ? "bg-red-500" :
                        item.type.includes("probability") || item.type.includes("status") ? "bg-purple-500" :
                        item.type.includes("followup") ? "bg-emerald-500" :
                        item.type.includes("review") ? "bg-violet-500" :
                        item.type.includes("recovery") || item.type.includes("transfer") ? "bg-orange-500" :
                        "bg-gray-600")} />
                      <div className="flex-1 min-w-0">
                        <p className="text-gray-300">{item.content}</p>
                        <p className="text-xs text-gray-600 mt-0.5 flex items-center gap-2">
                          {new Date(item.created_at).toLocaleString(lang === "zh" ? "zh-CN" : "en-GB")}
                          {"ai_generated" in item && (item as any).ai_generated && <span className="text-purple-500">🤖 AI</span>}
                          {"_type" in item && item._type === "event" && <span className="text-blue-500">{t("leadDetail.event")}</span>}
                        </p>
                      </div>
                    </div>
                  ))}
                {(activities.length === 0 && events.length === 0) && (
                  <p className="text-gray-600 text-sm text-center py-4">{t("leadDetail.noActivity")}</p>
                )}
              </div>
            </CardContent>
          </Card>
        </div>

        {/* ────── Right Sidebar ────── */}
        <div className="space-y-4">
          {/* Quick Actions */}
          <Card className="bg-gray-900 border-gray-800">
            <CardHeader className="pb-2">
              <CardTitle className="text-sm text-gray-400">{t("common.actions")}</CardTitle>
            </CardHeader>
            <CardContent className="space-y-2">
              {/* Stage selector */}
              <div>
                <p className="text-xs text-gray-500 mb-1.5">{lang === "zh" ? "更新阶段" : "Update Stage"}</p>
                <div className="flex flex-wrap gap-1">
                  {STAGES.map(s => (
                    <button key={s}
                      className={cn("text-[10px] px-2 py-1 rounded border transition-colors",
                        lead.stage === s ? "border-transparent text-white" : "border-gray-700 text-gray-400 hover:border-gray-500")}
                      style={lead.stage === s ? { backgroundColor: STAGE_COLORS[s]?.split(" ")[0]?.replace("/10", "/30") || "#6b7280" } : {}}
                      onClick={() => updateStage(s)}>{t(`stageLabels.${s}`)}</button>
                  ))}
                </div>
              </div>

              {/* Status selector */}
              <div>
                <p className="text-xs text-gray-500 mb-1.5">{t("leadDetail.customerStatus")}</p>
                <div className="flex gap-1 flex-wrap">
                  {Object.entries(STATUS_LABELS).map(([k, v]) => (
                    <button key={k}
                      className={cn("text-[10px] px-2 py-1 rounded border transition-colors",
                        lead.lead_status === k ? "border-transparent text-white" : "border-gray-700 text-gray-400 hover:border-gray-500")}
                      style={lead.lead_status === k ? {
                        backgroundColor: k === "hot" ? "#f43f5e" : k === "warm" ? "#f59e0b" : k === "cold" ? "#0ea5e9" : "#6b7280",
                      } : {}}
                      onClick={() => updateField("lead_status", k, "status_changed", `${lang === "zh" ? "客户状态" : "Status"}: ${v.label}`)}>
                      {v.label}
                    </button>
                  ))}
                </div>
              </div>

              <Separator className="bg-gray-800" />

              <Button variant="outline" size="sm"
                className="w-full border-gold-500/30 text-gold-400 justify-start"
                onClick={createQuote}>
                <Plus className="w-4 h-4 mr-2" />{t("leadDetail.createQuote")}
              </Button>
            </CardContent>
          </Card>

          {/* Contact Info */}
          <Card className="bg-gray-900 border-gray-800">
            <CardHeader className="pb-2">
              <CardTitle className="text-sm text-gray-400">{t("leadDetail.contactInfo")}</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3 text-sm">
              {lead.phone && <div className="flex items-center gap-2 text-gray-300"><Phone className="w-4 h-4 text-gray-500" />{lead.phone}</div>}
              {lead.email && <div className="flex items-center gap-2 text-gray-300"><MessageSquare className="w-4 h-4 text-gray-500" />{lead.email}</div>}
              {lead.location && <div className="flex items-center gap-2 text-gray-300"><MapPin className="w-4 h-4 text-gray-500" />{lead.location}</div>}
              {lead.property_type && <div className="flex items-center gap-2 text-gray-300"><Home className="w-4 h-4 text-gray-500" />{lead.property_type}{lead.property_size_sqm && ` · ${lead.property_size_sqm}㎡`}</div>}
              {lead.budget_range && <div className="text-gray-300">{lang === "zh" ? "预算" : "Budget"}: {lead.budget_range}</div>}
            </CardContent>
          </Card>

          {/* Manager Section */}
          <Card className="bg-gray-900 border-gray-800">
            <CardHeader className="pb-2">
              <CardTitle className="text-sm text-gray-400 flex items-center gap-2">
                <ShieldAlert className="w-4 h-4" /> {lang === "zh" ? "主管管理" : "Manager Section"}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-3 text-sm">
              <div className="flex items-center justify-between">
                <span className="text-gray-400">{t("leadDetail.responsible")}</span>
                <span className="text-white">{lead.rep_name || "—"}</span>
              </div>
              <Separator className="bg-gray-800" />

              {[
                { key: "sales_manager_review", label: lang === "zh" ? "主管审阅" : "Manager Review", color: "purple" },
                { key: "recovery_candidate", label: "Recovery Candidate", color: "orange" },
                { key: "transfer_candidate", label: "Transfer Candidate", color: "red" },
              ].map(({ key, label, color }) => (
                <div key={key} className="flex items-center justify-between">
                  <span className="text-gray-400">{label}</span>
                  <button
                    className={cn("px-2 py-0.5 rounded text-xs font-medium transition-colors",
                      (lead as any)[key]
                        ? `bg-${color}-500/20 text-${color}-400`
                        : "bg-gray-800 text-gray-500 hover:bg-gray-700")}
                    onClick={() => updateField(key, !(lead as any)[key],
                      (lead as any)[key] ? undefined : "manager_review_flagged",
                      (lead as any)[key] ? `${lang === "zh" ? "取消" : "Remove"}${label}` : `${lang === "zh" ? "标记" : "Flag"}${label}`)
                    }>
                    {(lead as any)[key] ? (lang === "zh" ? "✅ 是" : "✅ Yes") : (lang === "zh" ? "设置" : "Set")}
                  </button>
                </div>
              ))}

              <Separator className="bg-gray-800" />

              <div>
                <Label className="text-gray-500 text-xs">Hold Since</Label>
                {editField === "hold_since" ? (
                  <input type="date" autoFocus value={editValue} onChange={(e) => setEditValue(e.target.value)}
                    onBlur={() => updateField("hold_since", editValue || null)}
                    className="w-full h-8 text-xs bg-gray-800 border border-gray-700 rounded px-2 text-white mt-1" />
                ) : (
                  <p className="text-white mt-1 cursor-pointer hover:text-copper-400"
                    onClick={() => { setEditField("hold_since"); setEditValue(lead.hold_since || ""); }}>
                    {lead.hold_since ? new Date(lead.hold_since).toLocaleDateString(lang === "zh" ? "zh-CN" : "en-GB") : <span className="text-gray-600">{lang === "zh" ? "点击设置" : "Click to set"}</span>}
                  </p>
                )}
              </div>

              {/* Auto-rule info */}
              <div className="bg-gray-950 rounded-lg p-2.5 text-xs text-gray-500 space-y-1">
                <p className="font-medium text-gray-400">{lang === "zh" ? "自动规则" : "Auto Rules"}</p>
                <p>• {lang === "zh" ? "7天无跟进 → 🟡 黄色预警" : "7d no follow-up → 🟡 Yellow Alert"}</p>
                <p>• {lang === "zh" ? "14天无跟进 → 🔴 红色预警" : "14d no follow-up → 🔴 Red Alert"}</p>
                <p>• {lang === "zh" ? "报价后14天无动作 → Recovery Pool" : "No action 14d after quote → Recovery Pool"}</p>
                <p>• {lang === "zh" ? "报价后30天无动作 → Transfer Pool" : "No action 30d after quote → Transfer Pool"}</p>
                <p>• {lang === "zh" ? "概率≥70% + 14天无动作 → 主管审阅" : "Prob ≥70% + 14d stale → Manager Review"}</p>
                <p>• {lang === "zh" ? "Pending Decision超30天 → 主管审阅" : "Pending Decision >30d → Manager Review"}</p>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}
